data {
  int<lower=0> N;              // number of groups
  array[N] int<lower=0> n;     // trials
  array[N] int<lower=0> y;     // successes
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  // prior: p(alpha, beta) propto (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);
  // population model
  theta ~ beta(alpha, beta);
  // likelihood
  y ~ binomial(n, theta);
}

// Hierarchical binomial-beta model (BDA rat-tumor style)
//   y_i     ~ Binomial(n_i, theta_i)
//   theta_i ~ Beta(alpha, beta)
//   p(alpha, beta) propto (alpha + beta)^(-5/2)
//
// Sampling is done on the well-behaved scale
//   u = logit(alpha / (alpha + beta)),  v = log(alpha + beta)
// with the Jacobian of (alpha, beta) -> (u, v) added to the target, and the
// theta_i are integrated out analytically (Binomial-Beta => Beta-Binomial).
// The theta_i are recovered exactly in generated quantities from their
// conditional posterior Beta(alpha + y_i, beta + n_i - y_i).
data {
  int<lower=0> N;                 // number of groups
  array[N] int<lower=0> n;        // trials
  array[N] int<lower=0> y;        // successes
}
parameters {
  real u;                         // logit(alpha / (alpha + beta))
  real v;                         // log(alpha + beta)
}
transformed parameters {
  real<lower=0, upper=1> phi = inv_logit(u);
  real<lower=0> lambda = exp(v);
  real<lower=0> alpha = phi * lambda;
  real<lower=0> beta = (1 - phi) * lambda;
}
model {
  // prior p(alpha, beta) propto (alpha + beta)^(-5/2)
  target += -2.5 * v;
  // Jacobian: |d(alpha, beta) / d(u, v)| = lambda^2 * phi * (1 - phi)
  target += 2 * v + log(phi) + log1m(phi);
  // likelihood with theta integrated out
  y ~ beta_binomial(n, alpha, beta);
}
generated quantities {
  vector<lower=0, upper=1>[N] theta;
  for (i in 1 : N) {
    theta[i] = beta_rng(alpha + y[i], beta + n[i] - y[i]);
  }
}

// Hierarchical binomial-beta model (BDA rat-tumor style)
//   y_i     ~ Binomial(n_i, theta_i)
//   theta_i ~ Beta(alpha, beta)
//   p(alpha, beta) propto (alpha + beta)^(-5/2)
//
// The hyperparameters are sampled on the well-behaved scale
//   u = logit(alpha / (alpha + beta)),  v = log(alpha + beta)
// with the Jacobian of (alpha, beta) -> (u, v) added to the target, so the
// implied prior on (alpha, beta) is exactly (alpha + beta)^(-5/2).
data {
  int<lower=0> N;                 // number of groups
  array[N] int<lower=0> n;        // trials
  array[N] int<lower=0> y;        // successes
}
parameters {
  real u;                         // logit(alpha / (alpha + beta))
  real v;                         // log(alpha + beta)
  vector<lower=0, upper=1>[N] theta;
}
transformed parameters {
  real<lower=0, upper=1> phi = inv_logit(u);
  real<lower=0> lambda = exp(v);
  real<lower=0> alpha = phi * lambda;
  real<lower=0> beta = (1 - phi) * lambda;
}
model {
  // prior p(alpha, beta) propto (alpha + beta)^(-5/2)
  target += -2.5 * v;
  // Jacobian: |d(alpha, beta) / d(u, v)| = lambda^2 * phi * (1 - phi)
  target += 2 * v + log(phi) + log1m(phi);
  // population model and likelihood
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
